package com.candytaco.lighthome.ha

import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject

/** A dashboard from `lovelace/dashboards/list`; [urlPath] null is HA's default dashboard. */
data class DashboardInfo(val urlPath: String?, val title: String)

sealed interface DashboardState {
    data object Loading : DashboardState

    /** `lovelace/config` answered; may still be a strategy (auto-generated) config. */
    data class Loaded(val config: JsonObject) : DashboardState

    /** No stored config: the dashboard is auto-generated (`config_not_found`). */
    data object AutoGenerated : DashboardState

    data class Failed(val message: String) : DashboardState
}

data class DashboardData(
    val state: DashboardState = DashboardState.Loading,
    /** HA's dashboards, the default one first. */
    val dashboards: List<DashboardInfo> = listOf(DEFAULT_DASHBOARD),
    val selectedPath: String? = null,
) {
    val selectedTitle: String
        get() = dashboards.firstOrNull { it.urlPath == selectedPath }?.title ?: selectedPath ?: DEFAULT_DASHBOARD.title

    companion object {
        val DEFAULT_DASHBOARD = DashboardInfo(null, "Default dashboard")

        /** Parses `lovelace/dashboards/list`: `[{url_path, title, mode, …}]`. */
        fun parseList(result: JsonElement?): List<DashboardInfo> {
            val others = (result as? JsonArray).orEmpty().mapNotNull { element ->
                val obj = element as? JsonObject ?: return@mapNotNull null
                val path = obj.string("url_path") ?: return@mapNotNull null
                DashboardInfo(path, obj.string("title") ?: path)
            }
            return listOf(DEFAULT_DASHBOARD) + others
        }
    }
}
